## Cross-validation tests: verify NimNet algorithm outputs against
## reference values computed by NetworkX 3.6.
##
## Every expected value was generated by tests/generate_reference.py
## and verified against NetworkX. This ensures algorithmic correctness,
## not just structural properties.

import std/[unittest, tables, sets, math, sequtils, json]
import nimnet
import nimnet/algorithms/components as comp

const Eps = 1e-6
const EpsLoose = 1e-4  # for iterative algorithms (PageRank, HITS)

# ============================================================
# Helper: build the weighted graph from reference
# ============================================================
proc buildWeightedGraph(): Graph[int] =
  ## WG from generate_reference.py:
  ##   edges: (0,1,4), (0,2,2), (1,2,1), (1,3,5), (2,3,8), (2,4,10), (3,4,2)
  result = newGraph[int]()
  result.addWeightedEdge(0, 1, 4.0)
  result.addWeightedEdge(0, 2, 2.0)
  result.addWeightedEdge(1, 2, 1.0)
  result.addWeightedEdge(1, 3, 5.0)
  result.addWeightedEdge(2, 3, 8.0)
  result.addWeightedEdge(2, 4, 10.0)
  result.addWeightedEdge(3, 4, 2.0)

proc buildFlowGraph(): DiGraph[int] =
  ## FG from generate_reference.py
  result = newDiGraph[int]()
  result.addEdge(0, 1)
  var a01 = newEdgeAttr()
  a01["weight"] = newJString("10")
  result.setEdgeAttr(0, 1, a01)
  result.addEdge(0, 2)
  var a02 = newEdgeAttr()
  a02["weight"] = newJString("8")
  result.setEdgeAttr(0, 2, a02)
  result.addEdge(1, 3)
  var a13 = newEdgeAttr()
  a13["weight"] = newJString("5")
  result.setEdgeAttr(1, 3, a13)
  result.addEdge(1, 2)
  var a12 = newEdgeAttr()
  a12["weight"] = newJString("2")
  result.setEdgeAttr(1, 2, a12)
  result.addEdge(2, 4)
  var a24 = newEdgeAttr()
  a24["weight"] = newJString("10")
  result.setEdgeAttr(2, 4, a24)
  result.addEdge(3, 5)
  var a35 = newEdgeAttr()
  a35["weight"] = newJString("7")
  result.setEdgeAttr(3, 5, a35)
  result.addEdge(4, 3)
  var a43 = newEdgeAttr()
  a43["weight"] = newJString("8")
  result.setEdgeAttr(4, 3, a43)
  result.addEdge(4, 5)
  var a45 = newEdgeAttr()
  a45["weight"] = newJString("10")
  result.setEdgeAttr(4, 5, a45)

proc buildDirectedGraph(): DiGraph[int] =
  ## DG from generate_reference.py:
  ##   edges: (0,1), (1,2), (2,0), (2,3), (3,4), (4,3)
  result = newDiGraph[int]()
  result.addEdge(0, 1)
  result.addEdge(1, 2)
  result.addEdge(2, 0)
  result.addEdge(2, 3)
  result.addEdge(3, 4)
  result.addEdge(4, 3)

# ============================================================
# Karate Club Graph — comprehensive cross-validation
# ============================================================
suite "NetworkX cross-validation: Karate Club":
  let K = karateClubGraph()

  test "graph structure":
    check K.numberOfNodes() == 34
    check K.numberOfEdges() == 78

  test "shortest path 0→33 (length)":
    let sp = shortestPath(K, 0, 33)
    # Multiple valid shortest paths exist (e.g. [0,8,33] or [0,31,33])
    check sp.len == 3
    check sp[0] == 0
    check sp[^1] == 33
    check shortestPathLength(K, 0, 33) == 2

  test "diameter":
    check diameter(K) == 5

  test "radius":
    check radius(K) == 3

  test "center nodes":
    let c = center(K)
    # NetworkX: [0, 1, 2, 3, 8, 13, 19, 31]
    for n in [0, 1, 2, 3, 8, 13, 19, 31]:
      check n in c
    check c.len == 8

  test "eccentricity":
    check eccentricity(K, 0) == 3
    check eccentricity(K, 33) == 4
    check eccentricity(K, 2) == 3

  test "degree centrality top nodes":
    let dc = degreeCentrality(K)
    # NetworkX: node 33 = 0.5151515152, node 0 = 0.4848484848
    check abs(dc[33] - 0.5151515152) < Eps
    check abs(dc[0] - 0.4848484848) < Eps
    check abs(dc[32] - 0.3636363636) < Eps
    check abs(dc[2] - 0.3030303030) < Eps
    check abs(dc[1] - 0.2727272727) < Eps

  test "closeness centrality":
    let cc = closenessCentrality(K)
    check abs(cc[0] - 0.5689655172) < Eps
    check abs(cc[2] - 0.5593220339) < Eps
    check abs(cc[33] - 0.5500000000) < Eps

  test "betweenness centrality":
    let bc = betweennessCentrality(K)
    check abs(bc[0] - 0.4376352814) < Eps
    check abs(bc[2] - 0.1436568062) < Eps
    check abs(bc[33] - 0.3040749759) < Eps

  test "pagerank":
    let pr = pageRank(K)
    # Sum must be 1.0
    var total = 0.0
    for v in pr.values:
      total += v
    check abs(total - 1.0) < EpsLoose
    # NetworkX unweighted reference values (weight=None)
    check abs(pr[0] - 0.0970018176) < EpsLoose
    check abs(pr[2] - 0.0570784230) < EpsLoose
    check abs(pr[33] - 0.1009179167) < EpsLoose

  test "clustering coefficient":
    let cl = clustering(K)
    check abs(cl[0] - 0.1500000000) < Eps
    check abs(cl[2] - 0.2444444444) < Eps
    check abs(cl[33] - 0.1102941176) < Eps

  test "average clustering":
    check abs(averageClustering(K) - 0.5706384782) < Eps

  test "transitivity":
    check abs(transitivity(K) - 0.2556818182) < Eps

  test "triangle count":
    check triangles(K, 0) == 18
    check triangles(K, 33) == 15

  test "connectivity":
    check comp.isConnected(K) == true
    check numberOfConnectedComponents(K) == 1

  test "wiener index":
    check wienerIndex(K) == 1351

  test "global efficiency":
    check abs(globalEfficiency(K) - 0.4920083185) < Eps

  test "core number":
    let cn = coreNumber(K)
    check cn[0] == 4
    check cn[1] == 4
    check cn[2] == 4
    check cn[33] == 4

# ============================================================
# Petersen Graph
# ============================================================
suite "NetworkX cross-validation: Petersen Graph":
  let P = petersenGraph()

  test "graph structure":
    check P.numberOfNodes() == 10
    check P.numberOfEdges() == 15

  test "diameter":
    check diameter(P) == 2

  test "radius":
    check radius(P) == 2

  test "girth":
    check girth(P) == 5

  test "connectivity":
    check comp.isConnected(P) == true

  test "clustering":
    check abs(averageClustering(P) - 0.0) < Eps
    check abs(transitivity(P) - 0.0) < Eps

  test "wiener index":
    check wienerIndex(P) == 75

  test "pagerank symmetry":
    let pr = pageRank(P)
    # All nodes should have equal PageRank = 0.1
    for n in P.nodes:
      check abs(pr[n] - 0.1) < EpsLoose

  test "core number all 3":
    let cn = coreNumber(P)
    for n in P.nodes:
      check cn[n] == 3

# ============================================================
# Path Graph P5
# ============================================================
suite "NetworkX cross-validation: Path Graph P5":
  let P5 = pathGraph[int](5)

  test "distance measures":
    check diameter(P5) == 4
    check radius(P5) == 2
    let c = center(P5)
    check c == @[2]
    let p = periphery(P5)
    check 0 in p
    check 4 in p
    check p.len == 2

  test "betweenness centrality exact values":
    let bc = betweennessCentrality(P5)
    check abs(bc[0] - 0.0) < Eps
    check abs(bc[1] - 0.5) < Eps
    check abs(bc[2] - 0.6666666667) < Eps
    check abs(bc[3] - 0.5) < Eps
    check abs(bc[4] - 0.0) < Eps

  test "closeness centrality exact values":
    let cc = closenessCentrality(P5)
    check abs(cc[0] - 0.4) < Eps
    check abs(cc[1] - 0.5714285714) < Eps
    check abs(cc[2] - 0.6666666667) < Eps
    check abs(cc[3] - 0.5714285714) < Eps
    check abs(cc[4] - 0.4) < Eps

  test "shortest path":
    check shortestPath(P5, 0, 4) == @[0, 1, 2, 3, 4]

  test "wiener index":
    check wienerIndex(P5) == 20

