# ============================================================
# Directed Graph — PageRank, HITS, SCC
# ============================================================
suite "NetworkX cross-validation: Directed Graph":
  let dg = buildDirectedGraph()

  test "graph structure":
    check dg.numberOfNodes() == 5
    check dg.numberOfEdges() == 6

  test "pagerank exact values":
    let pr = pageRank(dg)
    check abs(pr[0] - 0.0773338144) < EpsLoose
    check abs(pr[1] - 0.0957337422) < EpsLoose
    check abs(pr[2] - 0.1113736809) < EpsLoose
    check abs(pr[3] - 0.3705733994) < EpsLoose
    check abs(pr[4] - 0.3449853631) < EpsLoose

  test "hits hub and authority values":
    let (hubs, auths) = hits(dg)
    # NetworkX HITS with L1 normalization (sum = 1)
    check abs(hubs[2] - 0.6180339887) < EpsLoose
    check abs(hubs[4] - 0.3819660113) < EpsLoose
    check abs(auths[0] - 0.3819660113) < EpsLoose
    check abs(auths[3] - 0.6180339887) < EpsLoose
    # Verify L1 norm (sum = 1)
    var hSum, aSum = 0.0
    for v in hubs.values: hSum += v
    for v in auths.values: aSum += v
    check abs(hSum - 1.0) < EpsLoose
    check abs(aSum - 1.0) < EpsLoose

  test "strongly connected components":
    let sccs = stronglyConnectedComponents(dg)
    check sccs.len == 2
    # SCC 1: {0, 1, 2}, SCC 2: {3, 4}
    var found012 = false
    var found34 = false
    for scc in sccs:
      if scc.len == 3 and 0 in scc and 1 in scc and 2 in scc:
        found012 = true
      if scc.len == 2 and 3 in scc and 4 in scc:
        found34 = true
    check found012
    check found34

# ============================================================
# Weighted Graph — Dijkstra, MST
# ============================================================
suite "NetworkX cross-validation: Weighted Graph":
  let wg = buildWeightedGraph()

  test "dijkstra path 0→4":
    let path = dijkstraPath(wg, 0, 4)
    # NetworkX: [0, 2, 1, 3, 4]
    check path == @[0, 2, 1, 3, 4]

  test "dijkstra path length 0→4":
    let length = dijkstraPathLength(wg, 0, 4)
    # NetworkX: 10.0  (0→2: 2, 2→1: 1, 1→3: 5, 3→4: 2)
    check abs(length - 10.0) < Eps

  test "dijkstra path 0→3":
    let path = dijkstraPath(wg, 0, 3)
    check path == @[0, 2, 1, 3]

  test "dijkstra path length 0→3":
    let length = dijkstraPathLength(wg, 0, 3)
    check abs(length - 8.0) < Eps

  test "kruskal MST weight":
    let w = kruskalMSTWeight(wg)
    # NetworkX: 10.0  (edges: (0,2)=2, (1,2)=1, (1,3)=5, (3,4)=2)
    check abs(w - 10.0) < Eps

  test "kruskal MST edges":
    let mst = kruskalMST(wg)
    check mst.numberOfEdges() == 4  # n-1 = 5-1 = 4
    check mst.numberOfNodes() == 5
    # Verify expected MST edges exist
    check mst.hasEdge(0, 2)
    check mst.hasEdge(1, 2)
    check mst.hasEdge(1, 3)
    check mst.hasEdge(3, 4)

