suite "NetworkX cross-validation: Max Flow":
  test "max flow value":
    let fg = buildFlowGraph()
    let val = maximumFlowValue(fg, 0, 5)
    # NetworkX: 15.0
    check abs(val - 15.0) < Eps

# ============================================================
# All Simple Paths
# ============================================================
suite "NetworkX cross-validation: All Simple Paths":
  var g = newGraph[int]()
  g.addEdge(0, 1)
  g.addEdge(0, 2)
  g.addEdge(1, 3)
  g.addEdge(2, 3)
  g.addEdge(1, 2)

  test "all paths 0→3":
    var paths: seq[seq[int]]
    for p in allSimplePaths(g, 0, 3):
      paths.add(p)
    # NetworkX: [[0,1,2,3], [0,1,3], [0,2,1,3], [0,2,3]]
    check paths.len == 4
    check @[0, 1, 2, 3] in paths
    check @[0, 1, 3] in paths
    check @[0, 2, 1, 3] in paths
    check @[0, 2, 3] in paths

  test "paths with cutoff=2":
    var paths: seq[seq[int]]
    for p in allSimplePaths(g, 0, 3, cutoff=2):
      paths.add(p)
    # NetworkX: [[0,1,3], [0,2,3]]
    check paths.len == 2
    check @[0, 1, 3] in paths
    check @[0, 2, 3] in paths

# ============================================================
# Graph Products
# ============================================================
suite "NetworkX cross-validation: Graph Products":
  let g1 = pathGraph[int](3)  # 0-1-2
  let g2 = pathGraph[int](2)  # 0-1

  test "cartesian product P3 × P2":
    let cp = cartesianProduct(g1, g2)
    check cp.numberOfNodes() == 6
    check cp.numberOfEdges() == 7

  test "tensor product P3 × P2":
    let tp = tensorProduct(g1, g2)
    check tp.numberOfNodes() == 6
    check tp.numberOfEdges() == 4

  test "strong product P3 × P2":
    let sp = strongProduct(g1, g2)
    check sp.numberOfNodes() == 6
    check sp.numberOfEdges() == 11

  test "lexicographic product P3 × P2":
    let lp = lexicographicProduct(g1, g2)
    check lp.numberOfNodes() == 6
    check lp.numberOfEdges() == 11

